INSERT INTO authority_progress_intent (
    progress_id, audit_id, investigation_id, run_id, progress_sequence, aggregate_version,
    authority_epoch, topic_name, idempotency_key, schema_version, canonical_content,
    canonical_sha256, status, attempt_count, eligible_at, created_at, updated_at
) VALUES (
    #{progressId}, #{auditId}, #{investigationId}, #{runId}, #{progressSequence}, #{aggregateVersion},
    #{authorityEpoch}, #{topicName}, #{idempotencyKey}, #{schemaVersion}, #{canonicalContent},
    #{canonicalSha256}, #{status}, #{attemptCount}, #{eligibleAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE authority_progress_intent
SET status='IN_FLIGHT', attempt_count=attempt_count+1, lease_owner=#{owner}, lease_token=#{token},
    lease_expires_at=#{expiresAt}, updated_at=#{now}
WHERE progress_id=#{progressId} AND status='PENDING' AND eligible_at <= #{now}

UPDATE authority_progress_intent
SET status='PENDING', eligible_at=#{now}, lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL,
    last_error_code='LEASE_EXPIRED', updated_at=#{now}
WHERE status='IN_FLIGHT' AND lease_expires_at <= #{now}

UPDATE authority_progress_intent
SET status='DELIVERED', delivered_at=#{now}, lease_owner=NULL, lease_token=NULL,
    lease_expires_at=NULL, last_error_code=NULL, updated_at=#{now}
WHERE progress_id=#{progressId} AND status='IN_FLIGHT' AND lease_token=#{token}
  AND lease_expires_at > #{now}

UPDATE authority_progress_intent
SET status='PENDING', eligible_at=#{eligibleAt}, lease_owner=NULL, lease_token=NULL,
    lease_expires_at=NULL, last_error_code=#{errorCode}, updated_at=#{now}
WHERE progress_id=#{progressId} AND status='IN_FLIGHT' AND lease_token=#{token}
  AND lease_expires_at > #{now}

UPDATE authority_progress_intent
SET status='DEAD', lease_owner=NULL, lease_token=NULL, lease_expires_at=NULL,
    last_error_code=#{errorCode}, updated_at=#{now}
WHERE progress_id=#{progressId} AND status='IN_FLIGHT' AND lease_token=#{token}
  AND lease_expires_at > #{now}
